pub fn score_node(
    job_cpu: u32,
    job_ram: u32,
    node_residual_cpu: u32,
    node_residual_ram: u32,
    node_capacity_cpu: u32,
    node_capacity_ram: u32,
    step_index: usize,
    total_jobs: usize,
    active_nodes_count: usize,
    mean_cpu_residual: f64,
    mean_ram_residual: f64,
    next_job_cpu: u32,
    next_job_ram: u32,
) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Introduce lookahead packing bonuses and imbalance penalties
    let lookahead_bonus = if node_residual_cpu >= next_job_cpu && node_residual_ram >= next_job_ram {
        0.7 - (imbalance_penalty / 20.0)
    } else {
        0.5 - (imbalance_penalty / 40.0)
    };

    // Introduce horizon-aware placement logic
    let horizon_bonus = if step_index < total_jobs / 4 {
        0.5
    } else if step_index < total_jobs / 2 {
        0.4
    } else {
        0.3
    };

    // Combine fine-grained residual fitting with lookahead anticipation
    let residual_fit_score = node_residual_cpu as f64 * (1.0 - cpu_norm) + node_residual_ram as f64 * (1.0 - ram_norm);
    let lookahead_anticipation_score = if step_index < total_jobs / 2 {
        ((next_job_cpu as f64 / node_capacity_cpu as f64).powi(2) + (next_job_ram as f64 / node_capacity_ram as f64).powi(2)) * 0.5
    } else {
        0.0
    };

    let score = -(imbalance_penalty * 0.3) + lookahead_bonus + residual_fit_score + lookahead_anticipation_score;
    let score = score * 0.98 + ((node_residual_ram as f64 / node_capacity_ram as f64) * 0.02);
    score
}

